local a=peripheral.find("modem")local b=require("index")local c=b.create()local function d(e,f)if f==nil then f="%s"end;local g={}for h in string.gmatch(e,"([^"..f.."]+)")do table.insert(g,h)end;return g end;local function i(j)local k=a.callRemote(j,"size")for l=1,k do local m=a.callRemote(j,"getItemDetail",l)if m==nil then return true end end;return false end;local function n()while true do local o=d(read()," ")if o[1]=="map"then if o[2]=="sender"then b.addSender(c,o[3])end;if o[2]=="receiver"then b.addReceiver(c,o[4],o[3])end end end end;local function p(q,r,l)local s=b.getReceiver(c,q)if i(s)then a.callRemote(r,"pushItems",s,l)print("Transferred from "..r.." to "..q)end end;local function t()while true do for u,v in ipairs(b.getAllSenders(c))do for l,m in pairs(a.callRemote(v,"list"))do local q=a.callRemote(v,"getItemDetail",l).package.getAddress()if m~=nil then p(q,v,l)end end end end end;if#arg>0 then if arg[1]==mapping then print("Mapping")n()else print("Transferring")t()end end
